ansible.builtin.shell.cmd:
P={{ d.prev | quote }}
git checkout -q --detach "$P" || exit $?
echo "OD-HEAD $(git rev-parse HEAD)"

T={{ d.tag | quote }}
P={{ d.prev | quote }}
{ GIT_COMMITTER_NAME=CredOps GIT_COMMITTER_EMAIL=credops@localhost git tag -fa "$T" -m "CredOps rollback" "$P" && git push -f origin "refs/tags/$T"; } || echo "OD-TAG failed rc=$?"

